package main

import (
	"go/parser"
	"go/token"
	"sort"
	"strings"
	"testing"
)

const splitFixture = `// Package openapi provides primitives to interact with the openapi HTTP API.
//
// Code generated by github.com/oapi-codegen/oapi-codegen/v2 version v2.8.0 DO NOT EDIT.
package openapi

import (
	"context"
	"net/http"

	"github.com/oapi-codegen/nullable"
)

// Defines values for ProjectKind.
const (
	ProjectKindA ProjectKind = "a"
)

// Project is only used by project operations.
type Project struct {
	Kind ProjectKind ` + "`json:\"kind\"`" + `
}

// ProjectKind is reached through Project.
type ProjectKind string

// Shared is used by both tags.
type Shared struct {
	Note nullable.Nullable[string]
}

// AsShared is a method that follows its receiver.
func (p Project) AsShared() Shared { return Shared{} }

// Dataset is only used by dataset operations.
type Dataset struct {
	Shared Shared
}

// GetProjectParams defines parameters for GetProject.
type GetProjectParams struct{}

// Client is shared plumbing.
type Client struct{}

// ClientInterface lists every operation and stays with the client.
type ClientInterface interface {
	GetProject(ctx context.Context, params *GetProjectParams) (*http.Response, error)
	GetDataset(ctx context.Context) (*http.Response, error)
}

func (c *Client) GetProject(ctx context.Context, params *GetProjectParams) (*http.Response, error) {
	_ = Project{}
	return nil, nil
}

func (c *Client) GetDataset(ctx context.Context) (*http.Response, error) {
	_ = Dataset{}
	return nil, nil
}

// NewGetProjectRequest builds a request.
func NewGetProjectRequest(server string, params *GetProjectParams) (*http.Request, error) {
	return nil, nil
}

// GetProjectResponse is parsed by ParseGetProjectResponse.
type GetProjectResponse struct {
	JSON200 *Project
}

// Status follows its receiver.
func (r GetProjectResponse) Status() string { return "" }

func ParseGetProjectResponse(rsp *http.Response) (*GetProjectResponse, error) { return nil, nil }

// NewClient is shared plumbing.
func NewClient(server string) (*Client, error) { return &Client{}, nil }
`

func TestSplitGeneratedByTag(t *testing.T) {
	files, err := splitGenerated([]byte(splitFixture), map[string]string{"GetProject": "Projects", "GetDataset": "DatasetSnapshots"})
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	if got := strings.Join(names, ","); got != "client.gen.go,dataset_snapshots.gen.go,models.gen.go,projects.gen.go" {
		t.Fatalf("files = %s", got)
	}

	want := map[string][]string{
		"client.gen.go":            {"type Client struct", "type ClientInterface interface", "func NewClient("},
		"models.gen.go":            {"type Shared struct"},
		"projects.gen.go":          {"ProjectKindA ProjectKind", "type Project struct", "type ProjectKind string", "func (p Project) AsShared()", "type GetProjectParams struct", "func (c *Client) GetProject(", "func NewGetProjectRequest(", "type GetProjectResponse struct", "func (r GetProjectResponse) Status()", "func ParseGetProjectResponse("},
		"dataset_snapshots.gen.go": {"type Dataset struct", "func (c *Client) GetDataset("},
	}
	for name, decls := range want {
		for _, decl := range decls {
			for other, content := range files {
				if strings.Contains(string(content), decl) != (other == name) {
					t.Errorf("%q in %s = %v", decl, other, other != name)
				}
			}
		}
	}

	for name, content := range files {
		if !strings.Contains(string(content), "Code generated by github.com/oapi-codegen/oapi-codegen/v2 version v2.8.0 DO NOT EDIT.") {
			t.Errorf("%s lacks the generated-code marker", name)
		}
		if strings.Contains(string(content), "// Package openapi") != (name == "client.gen.go") {
			t.Errorf("%s package doc placement is wrong", name)
		}
		// Each file must parse and import only what it uses.
		file, err := parser.ParseFile(token.NewFileSet(), name, content, parser.ImportsOnly)
		if err != nil {
			t.Fatalf("%s: %v\n%s", name, err, content)
		}
		for _, spec := range file.Imports {
			path := strings.Trim(spec.Path.Value, `"`)
			if !strings.Contains(string(content), path[strings.LastIndex(path, "/")+1:]+".") {
				t.Errorf("%s imports unused %s", name, path)
			}
		}
	}
	if !strings.Contains(string(files["models.gen.go"]), `"github.com/oapi-codegen/nullable"`) {
		t.Error("models.gen.go lost a needed import")
	}
}

func TestSplitGeneratedRejectsUnknownOperation(t *testing.T) {
	if _, err := splitGenerated([]byte(splitFixture), map[string]string{"GetProject": "Projects", "GetDataset": "Datasets", "DeleteProject": "Projects"}); err == nil {
		t.Fatal("expected an error for an operation without generated methods")
	}
}

func TestTagFileName(t *testing.T) {
	for tag, want := range map[string]string{"Projects": "projects.gen.go", "AiSecrets": "ai_secrets.gen.go", "SpanIframes": "span_iframes.gen.go", "Acls": "acls.gen.go"} {
		if got := tagFileName(tag); got != want {
			t.Errorf("tagFileName(%q) = %q, want %q", tag, got, want)
		}
	}
}
